{
  "name": "better-opencode-async-agents",
  "version": "0.10.0",
  "description": "Background task management plugin for OpenCode AI",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "bin",
    "README.md",
    "LICENSE",
    "CHANGELOG.md"
  ],
  "bin": {
    "bgagent-dashboard": "./bin/dashboard.mjs"
  },
  "keywords": [
    "opencode",
    "plugin",
    "background-task",
    "ai",
    "agent"
  ],
  "license": "MIT",
  "author": "paulpark",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/mainsoft-2024/better-opencode-async-agents.git"
  },
  "bugs": {
    "url": "https://github.com/mainsoft-2024/better-opencode-async-agents/issues"
  },
  "homepage": "https://github.com/mainsoft-2024/better-opencode-async-agents#readme",
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.0.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.0.0",
    "@biomejs/biome": "^1.9.4",
    "@semantic-release/changelog": "^6.0.3",
    "@types/bun": "^1.3.4",
    "semantic-release": "^24.2.3",
    "typescript": "^5.7.2"
  },
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --format esm --sourcemap=linked --external=bonjour-service",
    "build:types": "tsc --emitDeclarationOnly",
    "build:dashboard": "cd dashboard && bun install && bunx vite build",
    "build:all": "rm -rf dist && bun run build && bun run build:types && bun run build:dashboard && cp -r dashboard/dist dist/dashboard",
    "clean": "rm -rf dist",
    "lint": "biome check src/",
    "format": "biome format src/ --write",
    "check": "biome check src/",
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "bun run build:all && bun run typecheck && bun test",
    "deploy": "node scripts/deploy.mjs",
    "release": "semantic-release",
    "release:dry-run": "semantic-release --dry-run"
  },
  "release": {
    "branches": [
      "main",
      "master"
    ],
    "plugins": [
      "@semantic-release/commit-analyzer",
      "@semantic-release/release-notes-generator",
      [
        "@semantic-release/changelog",
        {
          "changelogFile": "CHANGELOG.md"
        }
      ],
      "@semantic-release/npm",
      "@semantic-release/github"
    ]
  },
  "dependencies": {
    "bonjour-service": "^1.3.0",
    "zod": "^4.3.5"
  }
}
